"""Validate Native source closure before yielding-gap measurements.

This module accepts original actor and camera readback only. A generated map
or controller request is not a measured highway designation or legal result.
"""

from __future__ import annotations

from hashlib import sha256
from math import hypot, isfinite
import json

from controlled_access_yield import FRAME_COUNT, FRAME_RATE
from multi_traffic_yield import assess_trace


VIEWS = ("overview", "approach", "reference_corner", "driver_reference")
HIGHWAY_IDS = {1, 2, 4}
RAMP_IDS = {3, 13}


def _actor(raw: dict, label: str) -> dict:
    if not isinstance(raw, dict):
        raise ValueError(f"missing {label} native readback")
    try:
        point = [float(v) for v in raw["center_xy_m"]]
        velocity = [float(v) for v in raw["velocity_xy_mps"]]
        radius = float(raw["radius_m"])
        road_id = int(raw["road_id"])
        lane_id = int(raw["lane_id"])
    except (KeyError, TypeError, ValueError) as exc:
        raise ValueError(f"invalid {label} native readback") from exc
    if len(point) != 2 or len(velocity) != 2 or not all(
        isfinite(v) for v in point + velocity + [radius]
    ) or radius <= 0 or lane_id != -1:
        raise ValueError(f"invalid {label} native geometry")
    return {"x_m": point[0], "y_m": point[1],
            "vx_mps": velocity[0], "vy_mps": velocity[1],
            "radius_m": radius, "road_id": road_id}


def bind_original(rows: list[dict], camera_rows: list[dict], context: dict,
                  policy: str) -> dict:
    """Require 600 joined original Native frames and four camera views."""
    if len(rows) != FRAME_COUNT or len(camera_rows) != FRAME_COUNT:
        raise ValueError("complete 600-frame native and camera sources required")
    if context.get("route_kind") != "entry" or context.get("map_source") != "native_opendrive_readback":
        raise ValueError("entry route and original map readback required")
    if not isinstance(context.get("map_sha256"), str) or len(context["map_sha256"]) != 64:
        raise ValueError("original map hash required")
    if context.get("controlled_access_designation_verified") is True:
        raise ValueError("authored map cannot establish legal designation")
    ids = context.get("approaching_vehicle_ids")
    if not isinstance(ids, list) or len(ids) < 2 or len(ids) != len(set(ids)):
        raise ValueError("two distinct inventoried highway vehicles required")
    network = {
        "route_kind": "entry", "highway_source": context["map_sha256"],
        "controlled_access_source": "designation_unresolved_original_map_geometry_only",
        "access_lane_id": "road3_or_13_lane-1",
        "highway_lane_id": "road1_or_2_or_4_lane-1",
        "conflict_point_source": context["map_sha256"] + ":junction100",
        "actor_inventory_source": context.get("actor_inventory_source"),
        "approaching_vehicle_ids": ids,
    }
    if not network["actor_inventory_source"]:
        raise ValueError("original actor inventory source required")
    measured = []
    saw_ramp = False
    saw_merge = False
    for i, (row, cameras) in enumerate(zip(rows, camera_rows)):
        if row.get("frame") != i or abs(row.get("time_s", -1) - i / FRAME_RATE) > 1e-6:
            raise ValueError("original native frame join failed")
        if cameras.get("frame") != row.get("native_frame") or set(cameras.get("views", {})) != set(VIEWS):
            raise ValueError("four exact original camera joins required")
        for view in VIEWS:
            if cameras["views"][view] != row["native_frame"]:
                raise ValueError("camera frame identity differs from native frame")
        ego = _actor(row.get("ego"), "ego")
        if ego["road_id"] not in RAMP_IDS | HIGHWAY_IDS:
            raise ValueError("ego left access/highway route")
        saw_ramp |= ego["road_id"] in RAMP_IDS
        saw_merge |= ego["road_id"] in {2, 4}
        traffic = row.get("traffic")
        if not isinstance(traffic, dict) or set(traffic) != set(ids):
            raise ValueError("original highway actor inventory differs")
        derived = {}
        for actor_id in ids:
            vehicle = _actor(traffic[actor_id], actor_id)
            if vehicle["road_id"] not in HIGHWAY_IDS:
                raise ValueError("inventoried vehicle left highway route")
            derived[actor_id] = {
                **{k: vehicle[k] for k in ("x_m", "y_m", "vx_mps", "vy_mps", "radius_m")},
                "distance_to_conflict_m": max(0.0, -vehicle["x_m"]),
                "on_highway": True,
                "approaching": vehicle["x_m"] < 0 and vehicle["vx_mps"] > 0,
            }
        measured.append({
            "frame": i, "time_s": row["time_s"],
            "ego": {**{k: ego[k] for k in ("x_m", "y_m", "vx_mps", "vy_mps", "radius_m")},
                    "distance_to_conflict_m": max(0.0, -ego["x_m"])},
            "traffic": derived,
            "ego_yielding": row.get("ego_yielding"),
        })
    if not saw_ramp or not saw_merge:
        raise ValueError("original ego entry traversal not observed")
    diagnostics = assess_trace(measured, network, policy)
    source_hash = sha256(json.dumps({"rows": rows, "cameras": camera_rows,
                                     "context": context}, sort_keys=True,
                                    separators=(",", ":"), allow_nan=False).encode()).hexdigest()
    return {"original_source_sha256": source_hash,
            "camera_views": list(VIEWS), "frames": FRAME_COUNT,
            "map_source_sha256": context["map_sha256"],
            "controlled_access_designation_verified": False,
            "measurements": diagnostics}

"""Source-shaped controlled-access yield controller and measurements.

The controller thresholds are engineering settings for diagnostics. They are
not definitions of immediate hazard or reasonable safety under NRS 484B.263.
"""

from __future__ import annotations

from math import hypot, isfinite

FRAME_COUNT = 600
FRAME_RATE = 20
POLICY_GAP_S = {"earlier_yield": 5.0, "later_yield": 2.5}


def control_request(policy: str, arrival_gap_s: float | None) -> dict:
    if policy not in POLICY_GAP_S:
        raise ValueError("unknown yield comparison policy")
    if arrival_gap_s is not None and (not isfinite(arrival_gap_s) or arrival_gap_s < 0):
        raise ValueError("invalid measured arrival gap")
    if arrival_gap_s is not None and arrival_gap_s < POLICY_GAP_S[policy]:
        return {"throttle": 0.0, "brake": 0.65, "yield_request": True}
    return {"throttle": 0.3, "brake": 0.0, "yield_request": False}


def measure_trace(rows: list[dict], network: dict) -> dict:
    if len(rows) != FRAME_COUNT:
        raise ValueError("source trace must contain 600 frames")
    if network.get("route_kind") not in ("entry", "exit"):
        raise ValueError("controlled-access entry or exit route required")
    required = ("highway_source", "controlled_access_source", "ramp_lane_id", "highway_lane_id", "conflict_point_source")
    if not all(network.get(k) for k in required) or network["ramp_lane_id"] == network["highway_lane_id"]:
        raise ValueError("sourced distinct highway and ramp lanes required")
    min_gap = float("inf")
    min_arrival_gap = float("inf")
    max_through_braking = 0.0
    through_presence = 0
    yield_frames = 0
    previous_through_speed = None
    for i, row in enumerate(rows):
        if row.get("frame") != i or abs(row.get("time_s", -1) - i / FRAME_RATE) > 1e-6:
            raise ValueError("source frame identity or 20 Hz join failed")
        keys = ("ego_x_m", "ego_y_m", "ego_vx_mps", "ego_vy_mps", "ego_radius_m",
                "through_x_m", "through_y_m", "through_vx_mps", "through_vy_mps", "through_radius_m",
                "ego_distance_to_conflict_m", "through_distance_to_conflict_m")
        try:
            v = [float(row[k]) for k in keys]
        except (KeyError, TypeError, ValueError) as exc:
            raise ValueError("raw actor geometry and conflict distances required") from exc
        if not all(isfinite(x) for x in v) or min(v[4], v[9]) <= 0 or min(v[10], v[11]) < 0:
            raise ValueError("invalid raw actor geometry and conflict distances")
        if type(row.get("through_on_highway")) is not bool or type(row.get("ego_yielding")) is not bool:
            raise ValueError("highway-presence and yielding source required")
        through_presence += int(row["through_on_highway"])
        yield_frames += int(row["ego_yielding"])
        ex, ey, evx, evy, er, tx, ty, tvx, tvy, tr, ed, td = v
        min_gap = min(min_gap, hypot(tx - ex, ty - ey) - er - tr)
        ego_speed, through_speed = hypot(evx, evy), hypot(tvx, tvy)
        if ego_speed > 0 and through_speed > 0 and row["through_on_highway"]:
            min_arrival_gap = min(min_arrival_gap, abs(ed / ego_speed - td / through_speed))
        if previous_through_speed is not None:
            max_through_braking = max(max_through_braking, (previous_through_speed - through_speed) * FRAME_RATE)
        previous_through_speed = through_speed
    if through_presence == 0:
        raise ValueError("approaching highway traffic source required")
    return {
        "frames": FRAME_COUNT,
        "duration_s": FRAME_COUNT / FRAME_RATE,
        "route_kind": network["route_kind"],
        "minimum_surface_gap_m": min_gap,
        "minimum_projected_arrival_gap_s": None if min_arrival_gap == float("inf") else min_arrival_gap,
        "maximum_through_deceleration_mps2": max_through_braking,
        "observed_yield_frames": yield_frames,
        "legal_immediate_hazard_conclusion": None,
        "legal_reasonable_safety_conclusion": None,
        "source_kind": "unverified_raw_actor_and_network_fields",
    }

"""Source-bound diagnostic of all approaching highway traffic at an access point.

The configured time gap is a controller setting, never a statutory hazard or
reasonable-safety threshold. The returned measurements make no legal finding.
"""

from __future__ import annotations

from math import hypot, isfinite
from hashlib import sha256
import json

from controlled_access_yield import FRAME_COUNT, FRAME_RATE, control_request


def _actor(raw: dict, label: str) -> dict:
    keys = ("x_m", "y_m", "vx_mps", "vy_mps", "radius_m", "distance_to_conflict_m")
    try:
        values = {key: float(raw[key]) for key in keys}
    except (KeyError, TypeError, ValueError) as exc:
        raise ValueError(f"missing raw {label} actor state") from exc
    if not all(isfinite(value) for value in values.values()):
        raise ValueError(f"nonfinite raw {label} actor state")
    if values["radius_m"] <= 0 or values["distance_to_conflict_m"] < 0:
        raise ValueError(f"invalid raw {label} actor geometry")
    values["speed_mps"] = hypot(values["vx_mps"], values["vy_mps"])
    return values


def assess_trace(rows: list[dict], network: dict, policy: str) -> dict:
    """Check complete 20 Hz actor snapshots and derive per-vehicle gap history."""
    if len(rows) != FRAME_COUNT:
        raise ValueError("source trace must contain 600 frames")
    if network.get("route_kind") not in ("entry", "exit"):
        raise ValueError("entry or exit route required")
    required = ("highway_source", "controlled_access_source", "access_lane_id",
                "highway_lane_id", "conflict_point_source", "actor_inventory_source")
    if not all(network.get(key) for key in required):
        raise ValueError("sourced controlled-access network and inventory required")
    if network["access_lane_id"] == network["highway_lane_id"]:
        raise ValueError("distinct access and highway lanes required")
    ids = network.get("approaching_vehicle_ids")
    if not isinstance(ids, list) or not ids or not all(
        isinstance(value, str) and value for value in ids
    ) or len(ids) != len(set(ids)):
        raise ValueError("nonempty unique approaching vehicle inventory required")

    minimum_gap = {actor_id: float("inf") for actor_id in ids}
    minimum_arrival_gap = {actor_id: float("inf") for actor_id in ids}
    maximum_deceleration = {actor_id: 0.0 for actor_id in ids}
    previous_speed: dict[str, float] = {}
    yield_request_frames = 0
    observed_yield_frames = 0
    traffic_present_frames = 0
    disagreements = 0
    for i, row in enumerate(rows):
        if row.get("frame") != i or abs(row.get("time_s", -1) - i / FRAME_RATE) > 1e-6:
            raise ValueError("source frame identity or 20 Hz join failed")
        ego = _actor(row.get("ego", {}), "ego")
        traffic = row.get("traffic")
        if not isinstance(traffic, dict) or set(traffic) != set(ids):
            raise ValueError("approaching vehicle inventory missing from frame")
        if type(row.get("ego_yielding")) is not bool:
            raise ValueError("observed ego yield source required")
        observed_yield_frames += int(row["ego_yielding"])
        arrival_gaps = []
        present = False
        for actor_id in ids:
            raw = traffic[actor_id]
            other = _actor(raw, actor_id)
            if type(raw.get("on_highway")) is not bool or type(raw.get("approaching")) is not bool:
                raise ValueError("highway presence and approach source required")
            if raw["approaching"] and not raw["on_highway"]:
                raise ValueError("approaching highway vehicle must have highway source")
            minimum_gap[actor_id] = min(
                minimum_gap[actor_id],
                hypot(other["x_m"] - ego["x_m"], other["y_m"] - ego["y_m"])
                - other["radius_m"] - ego["radius_m"],
            )
            if actor_id in previous_speed:
                maximum_deceleration[actor_id] = max(
                    maximum_deceleration[actor_id],
                    (previous_speed[actor_id] - other["speed_mps"]) * FRAME_RATE,
                )
            previous_speed[actor_id] = other["speed_mps"]
            if raw["approaching"]:
                present = True
                if ego["speed_mps"] > 0 and other["speed_mps"] > 0:
                    gap = abs(
                        ego["distance_to_conflict_m"] / ego["speed_mps"]
                        - other["distance_to_conflict_m"] / other["speed_mps"]
                    )
                    arrival_gaps.append(gap)
                    minimum_arrival_gap[actor_id] = min(minimum_arrival_gap[actor_id], gap)
        traffic_present_frames += int(present)
        # A present actor with unmeasurable arrival time keeps the diagnostic
        # controller in yield mode; missing speed is not a measured safe gap.
        request = control_request(policy, min(arrival_gaps) if arrival_gaps else (0.0 if present else None))
        yield_request_frames += int(request["yield_request"])
        disagreements += int(request["yield_request"] != row["ego_yielding"])
    if traffic_present_frames == 0:
        raise ValueError("approaching highway traffic never observed")
    return {
        "source_kind": "raw_actor_network_diagnostic",
        "frames": FRAME_COUNT,
        "duration_s": FRAME_COUNT / FRAME_RATE,
        "route_kind": network["route_kind"],
        "approaching_vehicle_ids": ids,
        "minimum_surface_gap_m_by_actor": minimum_gap,
        "minimum_projected_arrival_gap_s_by_actor": {
            actor_id: None if value == float("inf") else value
            for actor_id, value in minimum_arrival_gap.items()
        },
        "maximum_deceleration_mps2_by_actor": maximum_deceleration,
        "traffic_present_frames": traffic_present_frames,
        "controller_yield_request_frames": yield_request_frames,
        "observed_ego_yield_frames": observed_yield_frames,
        "controller_observation_disagreement_frames": disagreements,
        "legal_immediate_hazard_conclusion": None,
        "legal_reasonable_safety_conclusion": None,
    }


def compare_policies(rows: list[dict], network: dict) -> dict:
    """Run both engineering settings on identical source rows and network."""
    source_sha256 = sha256(json.dumps(
        {"rows": rows, "network": network}, sort_keys=True, separators=(",", ":"),
        allow_nan=False,
    ).encode()).hexdigest()
    early = assess_trace(rows, network, "earlier_yield")
    late = assess_trace(rows, network, "later_yield")
    assert early["minimum_surface_gap_m_by_actor"] == late["minimum_surface_gap_m_by_actor"]
    assert early["minimum_projected_arrival_gap_s_by_actor"] == late["minimum_projected_arrival_gap_s_by_actor"]
    return {
        "comparison_variable": "engineering_yield_request_gap_s",
        "fixed_source_sha256": source_sha256,
        "earlier_yield_request_frames": early["controller_yield_request_frames"],
        "later_yield_request_frames": late["controller_yield_request_frames"],
        "request_frame_difference": early["controller_yield_request_frames"] - late["controller_yield_request_frames"],
        "legal_comparison_conclusion": None,
    }
